use semio_framework_job_context::testkit;
use super::*;
#[test]fn genuine_child_cannot_open_an_unused_owned_budget_and_relends_the_actual_parent(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let quantum=RetainedCloneGrant{maximum_items:1,..stock};let mut caller=semio_framework_job_testing_caller::OriginalJobFixtureCaller::admit(OperationId(row["operation"].as_u64().unwrap()),Generation(row["generation"].as_u64().unwrap()),stock,||Some(1),u64::MAX,s["fuel"].as_u64().unwrap());caller.turn(quantum,|cx|testkit::admit_return_origin(cx)).unwrap();let mut child=caller.turn(quantum,|cx|Ok(OriginalCallerChildSource::new(cx.original_source_parent()?,cx,OperationId(row["childOperation"].as_u64().unwrap()),Generation(row["childGeneration"].as_u64().unwrap()))?)).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if testkit::child_source_status(&child).0{break}caller.turn(quantum,|cx|child.admit_step(cx.original_source_parent()?,cx)).unwrap();}assert!(testkit::child_source_status(&child).0);let mut sequence=0;let mut recipient=RetainedCloneProgress::default();let owned=child.parent().unwrap().borrow_context(StepBudget{fuel:s["fuel"].as_u64().unwrap(),deadline_us:u64::MAX,retained:stock},||Some(1),&mut sequence,&mut recipient);assert_eq!(serde_json::to_value(owned.is_err()).unwrap(),row["ownRouteRefused"]);drop(owned);assert_eq!(testkit::source_return_budget_is_bound(child.parent().unwrap()).unwrap(),row["unusedChildBankBound"].as_bool().unwrap());caller.turn(quantum,|cx|{let returned=child.with_context(cx.original_source_parent()?,cx,quantum,|nested|{assert_eq!(testkit::return_budget_is_inherited(nested),row["borrowedRoute"].as_bool().unwrap());Ok(())})?;returned.into_original().map_err(|_|semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"genuine inherited child receipt refused"))??;Ok(())}).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if child.terminal_is_empty(){break}caller.turn(quantum,|cx|child.close_step(cx.original_source_parent()?,cx)).unwrap();}assert!(child.terminal_is_empty());drop(child);caller.retire(stock);}
